SELECT 
FROM TBL_KPI_INDICATORS


        AND ORGID = #{params.orgId}


        AND KPICODE LIKE CONCAT('%', #{params.kpiCode}, '%')


        AND KPINAME LIKE CONCAT('%', #{params.kpiName}, '%')


        AND KPICATEGORY = #{params.kpiCategory}


        AND KPITYPE = #{params.kpiType}


        AND KPISTATUS = #{params.kpiStatus}


        AND CALCULATIONFREQUENCY = #{params.calculationFrequency}


        AND TREND = #{params.trend}


        AND DATASOURCE LIKE CONCAT('%', #{params.dataSource}, '%')


        AND CALCULATIONDATE >= #{params.startDate}


        AND CALCULATIONDATE <= #{params.endDate}


ORDER BY CREATETIME DESC

SELECT 
FROM TBL_KPI_INDICATORS
WHERE KPICODE = #{kpiCode} AND ORGID = #{orgId}

SELECT COUNT(1)
FROM TBL_KPI_INDICATORS
WHERE KPICODE = #{kpiCode} AND ORGID = #{orgId}

    AND KPIID != #{excludeId}

SELECT 
FROM TBL_KPI_INDICATORS
WHERE CALCULATIONFREQUENCY = #{calculationFrequency} 
AND KPISTATUS != 'INACTIVE' 
AND ORGID = #{orgId}
ORDER BY KPINAME

