UPDATE TBL_KPI_INDICATORS
SET CURRENTVALUE = #{currentValue},
    UPDATETIME = CURRENT_TIMESTAMP,
    UPDATEUSER = #{updateUser}
WHERE KPIID = #{kpiId}

UPDATE TBL_KPI_INDICATORS
SET KPISTATUS = #{kpiStatus},
    UPDATETIME = CURRENT_TIMESTAMP,
    UPDATEUSER = #{updateUser}
WHERE KPIID = #{kpiId}

UPDATE TBL_KPI_INDICATORS
SET TREND = #{trend},
    CHANGEPERCENTAGE = #{changePercentage},
    UPDATETIME = CURRENT_TIMESTAMP,
    UPDATEUSER = #{updateUser}
WHERE KPIID = #{kpiId}

UPDATE TBL_KPI_INDICATORS
