    UPDATETIME = CURRENT_TIMESTAMP,
    UPDATEUSER = #{updateUser}
WHERE KPIID IN

    #{kpiId}

mapper.select:
SELECT COUNT(*) AS totalCount, COUNT(CASE WHEN KPISTATUS = 'NORMAL' THEN 1 END) AS normalCount, COUNT(CASE WHEN KPISTATUS = 'WARNING' THEN 1 END) AS warningCount, COUNT(CASE WHEN KPISTATUS = 'CRITICAL' THEN 1 END) AS criticalCount, COUNT(CASE WHEN KPISTATUS = 'INACTIVE' THEN 1 END) AS inactiveCount, COUNT(CASE WHEN TREND = 'UP' THEN 1 END) AS upTrendCount, COUNT(CASE WHEN TREND = 'DOWN' THEN 1 END) AS downTrendCount, COUNT(CASE WHEN TREND = 'STABLE' THEN 1 END) AS stableTrendCount, AVG(CASE WHEN CURRENTVALUE IS NOT NULL AND TARGETVALUE IS NOT NULL AND TARGETVALUE > 0 THEN (CURRENTVALUE / TARGETVALUE * 100) END) AS avgCompletionRate FROM TBL_KPI_INDICATORS WHERE ORGID = #{orgId}
AND CALCULATIONDATE >= #{startDate}
AND CALCULATIONDATE <= #{endDate}

SELECT CALCULATIONDATE AS calculationDate, CURRENTVALUE AS currentValue, PREVIOUSVALUE AS previousValue, CHANGEPERCENTAGE AS changePercentage, TREND AS trend, KPISTATUS AS kpiStatus FROM TBL_KPI_INDICATORS WHERE KPIID = #{kpiId}
AND CALCULATIONDATE >= #{startDate}
AND CALCULATIONDATE <= #{endDate}
ORDER BY CALCULATIONDATE DESC

SELECT 
FROM TBL_KPI_INDICATORS
WHERE KPITYPE = #{kpiType} AND ORGID = #{orgId}
AND CURRENTVALUE IS NOT NULL
ORDER BY CURRENTVALUE DESC

    LIMIT #{limit}

SELECT KPIID AS kpiId, KPICODE AS kpiCode, KPINAME AS kpiName, CURRENTVALUE AS currentValue, TARGETVALUE AS targetValue, CHANGEPERCENTAGE AS changePercentage, TREND AS trend, CALCULATIONDATE AS calculationDate FROM TBL_KPI_INDICATORS WHERE KPIID IN
#{kpiId}
AND CALCULATIONDATE >= #{startDate}
AND CALCULATIONDATE <= #{endDate}
ORDER BY KPICODE, CALCULATIONDATE DESC

SELECT COUNT(*) AS totalKpis, COUNT(CASE WHEN CALCULATIONDATE = CURRENT_DATE THEN 1 END) AS todayCalculated, COUNT(CASE WHEN CALCULATIONDATE >= CURRENT_DATE - INTERVAL '7' DAY THEN 1 END) AS weekCalculated, COUNT(CASE WHEN CALCULATIONDATE >= CURRENT_DATE - INTERVAL '30' DAY THEN 1 END) AS monthCalculated, COUNT(CASE WHEN CALCULATIONDATE IS NULL THEN 1 END) AS neverCalculated, AVG(CASE WHEN CURRENTVALUE IS NOT NULL THEN CURRENTVALUE END) AS avgCurrentValue FROM TBL_KPI_INDICATORS WHERE ORGID = #{orgId}
AND CREATETIME >= #{startDate}
AND CREATETIME <= #{endDate}

SELECT KPITYPE AS kpiType, COUNT(*) AS totalCount, COUNT(CASE WHEN KPISTATUS = 'NORMAL' THEN 1 END) AS activeCount, AVG(CASE WHEN CURRENTVALUE IS NOT NULL AND TARGETVALUE IS NOT NULL AND TARGETVALUE > 0 THEN (CURRENTVALUE / TARGETVALUE * 100) END) AS avgCompletionRate, COUNT(CASE WHEN CALCULATIONDATE >= #{startDate} THEN 1 END) AS recentlyUsed FROM TBL_KPI_INDICATORS WHERE ORGID = #{orgId}
AND CREATETIME >= #{startDate}
AND CREATETIME <= #{endDate}
GROUP BY KPITYPE ORDER BY totalCount DESC
